class Solution {
  public int countValidSelections(int[] nums) {
    int count = 0;
    for (int start = 0; start < nums.length; start++) {
      if (nums[start] != 0) continue;
      for (int dir = -1; dir <= 1; dir += 2) {
        if (simulate(nums.clone(), start, dir)) count++;
      }
    }
    return count;
  }

  private boolean simulate(int[] a, int curr, int dir) {
    while (curr >= 0 && curr < a.length) {
      if (a[curr] == 0) {
        curr += dir;
      } else {
        a[curr]--;
        dir = -dir;
        curr += dir;
      }
    }
    for (int v : a) if (v != 0) return false;
    return true;
  }
}
